import{_ as e,o as a,c as s,ao as i}from"./chunks/framework.CGAfXaNK.js";const c=JSON.parse('{"title":"3D meshes","description":"","frontmatter":{},"headers":[],"relativePath":"data/mesh3d.md","filePath":"data/mesh3d.md","lastUpdated":null}'),h={name:"data/mesh3d.md"};function l(d,t,o,n,r,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="3D-meshes" tabindex="-1">3D meshes <a class="header-anchor" href="#3D-meshes" aria-label="Permalink to &quot;3D meshes {#3D-meshes}&quot;">​</a></h1><p>In 3D the forward problem is solved by ModEM, but the mesh still has to come from somewhere. In this section we build a 3D mesh from a data file, move a model from one mesh to another, and pull the topography and water out of a model.</p><h2 id="Build-a-3D-mesh" tabindex="-1">Build a 3D mesh <a class="header-anchor" href="#Build-a-3D-mesh" aria-label="Permalink to &quot;Build a 3D mesh {#Build-a-3D-mesh}&quot;">​</a></h2><p><code>MakeMesh3D</code> reads a ModEM data file and writes a start model and a matching ModEM covariance file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/make_mesh3D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.rho</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dem.tif</span></span></code></pre></div><p>or, from Julia:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MakeMesh3D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; out_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;start.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, topo_file </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;dem.tif&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, topo_crs </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;EPSG:26918&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, mode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :nogui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The model (<code>mesh_start_model.rho</code> unless you name it) and the covariance (<code>C3.dat</code>) are written next to each other. <code>mode = :gui</code> opens a window where you can change the settings and see the mesh update.</p><p><code>topo_file</code> is optional. It is a digital elevation model (DEM) in the coordinate system <code>topo_crs</code>. With it, the ground surface is cut into the mesh as air cells and the station depths in the data are set from the DEM.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Setting</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>cell_width_frac</code></td><td style="text-align:left;">0.5</td><td style="text-align:left;">core cell width, as a fraction of the station spacing</td></tr><tr><td style="text-align:left;"><code>n_pad</code>, <code>pad_factor</code></td><td style="text-align:left;">12, 1.5</td><td style="text-align:left;">number of padding cells on each side, and their growth</td></tr><tr><td style="text-align:left;"><code>first_layer_div</code></td><td style="text-align:left;">4</td><td style="text-align:left;">first layer = skin depth at the highest frequency / this</td></tr><tr><td style="text-align:left;"><code>vertical_factor</code></td><td style="text-align:left;">1.2</td><td style="text-align:left;">growth of the layers with depth</td></tr><tr><td style="text-align:left;"><code>depth_mult</code></td><td style="text-align:left;">3</td><td style="text-align:left;">model depth = this × skin depth at the lowest frequency</td></tr><tr><td style="text-align:left;"><code>air_layers</code></td><td style="text-align:left;">6</td><td style="text-align:left;">number of air layers above the highest ground</td></tr><tr><td style="text-align:left;"><code>cov_value</code></td><td style="text-align:left;">0.3</td><td style="text-align:left;">smoothing written to the covariance file</td></tr></tbody></table><h2 id="Move-a-model-to-another-mesh" tabindex="-1">Move a model to another mesh <a class="header-anchor" href="#Move-a-model-to-another-mesh" aria-label="Permalink to &quot;Move a model to another mesh {#Move-a-model-to-another-mesh}&quot;">​</a></h2><p>Often you want to start one inversion from the result of another, on a finer or coarser mesh. <code>MeshToMesh</code> resamples a model onto a target mesh:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MeshToMesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vfsa_best.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fine_mesh.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>It writes three files into a new timestamped folder next to the target mesh: the resampled model, a copy of the data with the station depths moved onto the new ground surface, and a matching covariance file.</p><p>The target mesh keeps its own topography and water. Only its earth cells are filled from the source model. <code>method = :nearest</code> (the default) keeps sharp contrasts, and <code>method = :linear</code> smooths them.</p><h2 id="Topography-and-water-from-a-model" tabindex="-1">Topography and water from a model <a class="header-anchor" href="#Topography-and-water-from-a-model" aria-label="Permalink to &quot;Topography and water from a model {#Topography-and-water-from-a-model}&quot;">​</a></h2><p>A model with topography stores the air as very high resistivity. You can extract the ground surface, or the sea floor, as a table:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_ws3d_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">topo  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> extract_topography</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bathy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> extract_bathymetry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m; water_log10 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># cells below 2 Ω·m at the surface are water</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">write_bathymetry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bathymetry.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bathy)</span></span></code></pre></div><p>A bathymetry file like this tells <a href="./../inversion/3d_vfsa">3D VFSA</a> which cells are sea and should stay fixed.</p>`,19)])])}const g=e(h,[["render",l]]);export{c as __pageData,g as default};
